"""Readability scoring (Flesch Reading Ease & Flesch-Kincaid Grade)."""

import re

VOWELS = set("aeiouy")
WORD_RE = re.compile(r"[A-Za-z']+")
SENTENCE_SPLIT_RE = re.compile(r"[.!?\s]+")


def count_syllables(word):
    """Count syllables using an explicit heuristic.

    Rules:
      - Lowercase the word.
      - Count maximal runs of vowels (a, e, i, o, u, y); each run = 1 syllable.
      - Subtract 1 if the word ends in a silent 'e': ends with 'e'
        but not with 'le' preceded by a consonant.
      - Minimum result is 1.
    """
    w = word.lower()
    count = 0
    prev_is_vowel = False
    for ch in w:
        if ch in VOWELS:
            if not prev_is_vowel:
                count += 1
            prev_is_vowel = True
        else:
            prev_is_vowel = False

    # Silent 'e': word ends with 'e', unless it's an 'le' ending where
    # the 'l' is preceded by a consonant (e.g. "little", "table").
    if w.endswith("e"):
        ends_consonant_le = (
            w.endswith("le") and len(w) >= 3 and w[-3] not in VOWELS
        )
        if not ends_consonant_le:
            count -= 1

    return max(count, 1)


def _stats(text):
    words = WORD_RE.findall(text)
    sentences = [s for s in SENTENCE_SPLIT_RE.split(text) if s.strip()]
    syllables = sum(count_syllables(w) for w in words)
    return words, sentences, syllables


def flesch(text):
    """Flesch Reading Ease score."""
    words, sentences, syllables = _stats(text)
    if not words or not sentences:
        return 0.0
    return (
        206.835
        - 1.015 * (len(words) / len(sentences))
        - 84.6 * (syllables / len(words))
    )


def fk_grade(text):
    """Flesch-Kincaid Grade Level."""
    words, sentences, syllables = _stats(text)
    if not words or not sentences:
        return 0.0
    return (
        0.39 * (len(words) / len(sentences))
        + 11.8 * (syllables / len(words))
        - 15.59
    )

