import pytest

from readability import count_syllables, flesch, fk_grade

PASSAGE = "The cat sat on the mat. It was happy."


@pytest.fixture
def syllable_table():
    return {
        "cake": 1,
        "little": 2,
        "beautiful": 3,
        "education": 4,
        "queue": 1,
        "rhythm": 1,
        "table": 2,
        "strengths": 1,
    }


def test_count_syllables_table(syllable_table):
    for word, expected in syllable_table.items():
        assert count_syllables(word) == expected, f"failed for {word!r}"


@pytest.fixture
def passage_stats():
    from readability import _stats

    return _stats(PASSAGE)


def test_passage_word_count(passage_stats):
    words, _, _ = passage_stats
    assert len(words) == 9


def test_passage_sentence_count(passage_stats):
    _, sentences, _ = passage_stats
    assert len(sentences) == 2


def test_passage_syllable_count(passage_stats):
    _, _, syllables = passage_stats
    assert syllables == 10


def test_passage_flesch():
    assert abs(flesch(PASSAGE) - 108.27) < 0.01


def test_passage_fk_grade():
    assert abs(fk_grade(PASSAGE) - (-0.72)) < 0.01

